def fix_romanian(text: str) -> str:
    replacement_map = {
        'ş': 'ș',
        'Ş': 'Ș',
        'ţ': 'ț',
        'Ţ': 'Ț'
    }

    result = text
    for old_char, new_char in replacement_map.items():
        result = result.replace(old_char, new_char)

    return result
