    translation_table = str.maketrans({
        '\u015F': '\u0219',  # ș (small s with cedilla -> small s with comma below)
        '\u015E': '\u0218',  # Ș (capital S with cedilla -> capital S with comma below)
        '\u0163': '\u021b',  # ț (small t with cedilla -> small t with comma below)
        '\u0162': '\u021a',  # Ț (capital T with cedilla -> capital T with comma below)
    })
    return text.translate(translation_table)
